<script setup>
import { computed, ref, watch } from 'vue'
import UiIcon from './UiIcon.vue'
import { categorySegments, money, percent, trendPoints } from '../lib/salesDashboard.js'

const props = defineProps({ report: Object, loading: Boolean, error: String })
const emit = defineEmits(['upload', 'refresh', 'filter'])
const start = ref(''), end = ref('')
const refundView = ref('products')
const colors = ['#7463e8', '#40b6a7', '#eeb665', '#639fe0', '#df8dad', '#b6bfd0']
watch(() => props.report, (report) => { start.value = report?.start || ''; end.value = report?.end || '' }, { immediate: true })
const r = computed(() => props.report)
const refund = computed(() => r.value?.refund_analysis || {})
const daily = computed(() => r.value?.daily || [])
const chartMax = computed(() => Math.max(1, ...daily.value.map(item => Number(item.paid) || 0)))
const points = key => trendPoints(daily.value, key, chartMax.value).map(pair => pair.join(',')).join(' ')
const area = computed(() => daily.value.length > 1 ? `60,190 ${points('net')} 690,190` : '')
const xLabels = computed(() => {
  const items = daily.value
  return [...new Set([0, Math.floor((items.length - 1) / 2), items.length - 1])].filter(index => index >= 0).map(index => ({ label: items[index].date.slice(5), x: items.length === 1 ? 360 : 60 + index / (items.length - 1) * 630 }))
})
const segments = computed(() => categorySegments(r.value?.categories || [], r.value?.summary?.paid))
const donutStyle = computed(() => {
  let cursor = 0
  const stops = segments.value.map((item, index) => { const begin = cursor; cursor += item.share * 100; return `${colors[index % colors.length]} ${begin}% ${cursor}%` })
  return { background: stops.length ? `conic-gradient(${stops.join(',')})` : '#edf0f7' }
})
const refundRows = computed(() => (refundView.value === 'categories' ? refund.value.top_categories : refund.value.top_products) || [])
const maxRefund = computed(() => Math.max(1, ...refundRows.value.map(item => Number(item.refund))))
const cards = computed(() => !r.value ? [] : [
  { key: 'paid', title: '实收销售额', value: money(r.value.summary.paid), unit: r.value.currency, note: '成功支付的商品行实收', tone: 'purple' },
  { key: 'net', title: '净销售额', value: money(r.value.summary.net), unit: r.value.currency, note: '实收减同批订单累计退款', tone: 'green' },
  { key: 'orders', title: '支付订单数', value: r.value.summary.orders, unit: '单', note: `客单价 ${money(r.value.summary.aov)} ${r.value.currency}`, tone: 'blue' },
  { key: 'refund', title: '金额退款率', value: percent(refund.value.amount_rate), unit: '', note: `累计退款 ${money(r.value.summary.refund)} ${r.value.currency}`, tone: 'orange' },
])
const changed = computed(() => start.value !== r.value?.start || end.value !== r.value?.end)
</script>

<template>
  <div class="sales-dashboard">
    <div class="sales-intro"><div><span class="sales-eyebrow">SALES OVERVIEW</span><h2>看清销售，找到下一步。</h2><p>销售表现、品类贡献与售后风险，在同一处复盘。</p></div><button class="sales-import" :disabled="loading" @click="emit('upload')"><UiIcon name="upload" :size="16" />导入订单CSV</button></div>
    <div v-if="error" class="sales-error" role="alert">{{ error }}<button @click="emit('refresh')">重试</button></div>
    <div v-if="loading && !report" class="sales-empty" role="status"><span class="sales-spinner"></span><h3>正在读取销售报表</h3></div>
    <div v-else-if="!report" class="sales-empty"><span class="sales-empty-icon"><UiIcon name="chart" :size="32" /></span><h3>从一份订单CSV开始</h3><p>导入后，这里将展示销售趋势、品类分布、退款排行和经营建议。</p><button class="sales-import" @click="emit('upload')">选择订单文件</button><small>支持中英文表头 · 最大10MB / 50000行</small></div>
    <template v-else>
      <div class="sales-filter"><div class="sales-period"><span class="data-dot"></span><strong>{{ report.data_label || '报表快照' }}</strong><span>{{ report.start }} — {{ report.end }}</span></div><div class="sales-date-inputs" v-if="report.analysis_options"><label>开始<input v-model="start" type="date" :disabled="loading" /></label><label>结束<input v-model="end" type="date" :disabled="loading" /></label><button :disabled="loading || !changed || !start || !end" @click="emit('filter', { start_date: start, end_date: end })">{{ loading ? '更新中…' : '更新统计' }}</button></div><button v-else class="sales-text-button" @click="emit('upload')">重新导入启用完整分析</button></div>
      <div class="sales-kpis"><article v-for="card in cards" :key="card.key" :class="['sales-kpi', card.tone]"><div><span>{{ card.title }}</span><span class="kpi-dot"></span></div><strong>{{ card.value }}<small>{{ card.unit }}</small></strong><p>{{ card.note }}</p></article></div>
      <div class="sales-main-grid">
        <section class="sales-panel trend-panel"><div class="panel-heading"><div><h3>销售趋势</h3><p>按支付日统计 · {{ report.currency }}</p></div><div class="chart-legend"><span><i class="legend-paid"></i>实收</span><span><i></i>净额</span></div></div><div v-if="daily.length" class="trend-chart"><svg viewBox="0 0 720 220" role="img" aria-label="每日实收与净销售额趋势图"><g v-for="step in [0, 1, 2, 3]" :key="step"><line x1="60" :y1="40 + step * 50" x2="690" :y2="40 + step * 50" stroke="#edf0f6" /><text x="49" :y="44 + step * 50" text-anchor="end" class="axis-label">{{ Number(chartMax * (3 - step) / 3).toLocaleString('zh-CN', { maximumFractionDigits: 0 }) }}</text></g><polygon :points="area" fill="#7463e812" /><polyline :points="points('paid')" fill="none" stroke="#b7bfd3" stroke-width="2" stroke-dasharray="5 5" /><polyline :points="points('net')" fill="none" stroke="#7463e8" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" /><circle v-if="daily.length === 1" cx="360" :cy="190 - Number(daily[0].net) / chartMax * 150" r="4" fill="#7463e8" /><text v-for="label in xLabels" :key="label.x" :x="label.x" y="213" text-anchor="middle" class="axis-label">{{ label.label }}</text></svg></div><p v-else class="panel-empty">暂无日趋势数据</p><div class="trend-footer"><span>购买人数 <b>{{ report.summary.buyers ?? '不可计算' }}</b></span><span>支付件数 <b>{{ report.summary.quantity ?? '不可计算' }}</b></span><span>纳入 <b>{{ report.included_lines }}</b> 行 · 排除 {{ report.excluded_lines }} 行</span></div></section>
        <section class="sales-panel category-panel"><div class="panel-heading"><div><h3>品类销售结构</h3><p>按实收销售额占比</p></div><span class="panel-tag">{{ report.category_coverage?.total_categories || 0 }} 个品类</span></div><template v-if="segments.length"><div class="category-visual"><div class="sales-donut" :style="donutStyle" role="img" aria-label="品类实收销售额占比分布"><div><small>销售品类</small><strong>{{ report.category_coverage?.total_categories }}</strong></div></div><div class="category-legend"><div v-for="(item, index) in segments" :key="item.name"><i :style="{ background: colors[index % colors.length] }"></i><span :title="item.name">{{ item.name }}</span><strong>{{ percent(item.share) }}</strong></div></div></div></template><p v-else class="panel-empty">{{ report.category_coverage?.available ? '当前区间暂无品类销售额' : '缺少品类信息。导入时匹配“品类”字段后，即可展示结构与品类建议。' }}</p></section>
      </div>
      <div class="sales-secondary-grid">
        <section class="sales-panel refund-panel"><div class="panel-heading"><div><h3>退款重点关注</h3><p>按累计退款金额排序，最多5项</p></div><div class="sales-toggle"><button :class="{ active: refundView === 'products' }" @click="refundView = 'products'">商品</button><button :class="{ active: refundView === 'categories' }" @click="refundView = 'categories'">品类</button></div></div><div class="refund-overview"><div><small>退款金额</small><strong>{{ money(report.summary.refund) }}<span>{{ report.currency }}</span></strong></div><div><small>退款订单率</small><strong>{{ percent(refund.order_rate) }}</strong><span>{{ refund.refunded_orders ?? '—' }} / {{ refund.paid_orders ?? report.summary.orders }} 单</span></div></div><div v-if="refundRows.length" class="refund-bars"><div v-for="(item, index) in refundRows" :key="item.id" class="refund-row"><span class="refund-rank">{{ String(index + 1).padStart(2, '0') }}</span><div><div class="refund-row-title"><strong :title="item.name">{{ item.name }}</strong><b>{{ money(item.refund) }}</b></div><div class="refund-bar-track"><span :style="{ width: `${Math.min(100, Number(item.refund) / maxRefund * 100)}%` }"></span></div><small>金额退款率 {{ percent(item.refund_rate) }} · {{ item.refunded_orders }} 笔退款订单</small></div></div></div><p v-else class="panel-empty">{{ refund.assumed_no_refunds ? '当前为确认无退款的假设，请补齐实际售后数据再评估风险。' : refundView === 'categories' && !report.category_coverage?.available ? '缺少品类字段，暂不能按品类拆解退款。' : report.refund_analysis ? '当前区间没有已记录的退款。请在售后窗口结束后继续复查。' : '历史报表缺少退款诊断，请重新导入CSV。' }}</p></section>
        <section class="sales-panel advice-panel"><div class="panel-heading"><div><h3>经营建议</h3><p>每条建议均附当前订单数据依据</p></div><span class="advice-mark"><UiIcon name="spark" :size="16" />数据洞察</span></div><div v-if="report.recommendations?.length" class="advice-list"><article v-for="item in report.recommendations" :key="item.id" :class="['advice-item', { 'refund-advice': item.topic === '退款' }]"><div class="advice-labels"><span>{{ item.topic }}</span><small>{{ item.priority }}</small></div><h4>{{ item.title }}</h4><p class="advice-evidence">{{ item.evidence }}</p><ul><li v-for="action in item.actions" :key="action">{{ action }}</li></ul><p class="advice-measure">跟踪指标：{{ item.measure }}</p></article></div><p v-else class="panel-empty">重新导入CSV后，可生成基于品类贡献和退款表现的建议。</p><p class="advice-note">建议依据当前快照生成。售后原因、库存与毛利需要进一步核实，数据相关性不代表因果。</p></section>
      </div>
      <section v-if="report.categories?.length" class="sales-panel category-table-panel"><div class="panel-heading"><div><h3>品类经营明细</h3><p>金额单位 {{ report.currency }} · 占比基于全店实收</p></div><a v-if="report.artifacts.categories_csv" :href="report.artifacts.categories_csv">下载品类CSV</a></div><div class="sales-table-scroll"><table><thead><tr><th>品类</th><th>实收销售额</th><th>销售占比</th><th>退款金额</th><th>净销售额</th><th>金额退款率</th><th>支付订单</th></tr></thead><tbody><tr v-for="item in report.categories" :key="item.id"><td>{{ item.name }}</td><td>{{ money(item.paid) }}</td><td>{{ percent(item.sales_share) }}</td><td class="refund-amount">{{ money(item.refund) }}</td><td>{{ money(item.net) }}</td><td>{{ percent(item.refund_rate) }}</td><td>{{ item.orders }}</td></tr></tbody></table></div></section>
      <details class="sales-notes"><summary>统计口径与数据说明</summary><ul><li v-for="note in report.notes" :key="note">{{ note }}</li></ul></details><div class="sales-downloads"><span>报表导出</span><a :href="report.artifacts.summary_csv">汇总CSV</a><a :href="report.artifacts.products_csv">商品明细</a><a :href="report.artifacts.daily_csv">每日统计</a><a :href="report.artifacts.dashboard" target="_blank" rel="noopener noreferrer">独立报表 ↗</a><button :disabled="loading" @click="emit('refresh')">刷新报表</button></div>
    </template>
  </div>
</template>

<style scoped>
