.sales-kpis { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:15px; margin-bottom:20px; }.sales-kpi { background:#fff; border:1px solid #e9edf5; padding:19px 18px 16px; border-radius:12px; min-width:0; }.sales-kpi > div { display:flex; align-items:center; justify-content:space-between; gap:8px; font-size:11px; color:#8b94a8; }.kpi-dot { height:8px; width:8px; border-radius:3px; background:#7463e8; }.green .kpi-dot { background:#42b6a6; }.blue .kpi-dot { background:#639fe0; }.orange .kpi-dot { background:#e6a36a; }.sales-kpi > strong { display:block; font-size:26px; margin-top:14px; font-weight:650; letter-spacing:-.8px; overflow-wrap:anywhere; }.sales-kpi strong small { font-size:10px; margin-left:7px; font-weight:400; letter-spacing:0; color:#9aa1b1; }.sales-kpi p { font-size:10px; color:#9aa1b1; margin:8px 0 0; }.sales-main-grid { display:grid; grid-template-columns:minmax(0,1.65fr) minmax(0,1fr); gap:20px; }.sales-panel { min-width:0; background:#fff; border:1px solid #e9edf5; border-radius:13px; padding:21px; }.panel-heading { display:flex; justify-content:space-between; align-items:flex-start; gap:12px; margin-bottom:22px; }.panel-heading h3 { font-size:14px; margin:0; font-weight:650; }.panel-heading p { font-size:10px; color:#a0a8b7; margin:7px 0 0; }.panel-heading > a { font-size:11px; color:#7463e8; text-decoration:none; white-space:nowrap; }.chart-legend { display:flex; gap:13px; color:#8b94a8; font-size:10px; padding-top:4px; white-space:nowrap; }.chart-legend span { display:flex; align-items:center; gap:5px; }.chart-legend i { display:inline-block; height:5px; width:12px; background:#7463e8; border-radius:3px; }.chart-legend .legend-paid { background:#b7bfd3; }.trend-chart svg { display:block; width:100%; height:auto; }.axis-label { fill:#a2abbd; font-size:12px; }.trend-footer { border-top:1px solid #f0f2f7; margin-top:8px; padding-top:14px; display:flex; justify-content:space-between; gap:10px; flex-wrap:wrap; font-size:10px; color:#9aa