splay:grid; gap:20px; }.refund-row { display:grid; grid-template-columns:23px minmax(0,1fr); gap:10px; }.refund-rank { padding-top:2px; color:#b9b2b0; font-size:11px; }.refund-row-title { display:flex; justify-content:space-between; gap:12px; font-size:11px; }.refund-row-title strong { color:#62708a; font-weight:500; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; }.refund-row-title b { font-weight:550; color:#8c6e5a; }.refund-bar-track { height:5px; background:#f5f0ed; border-radius:8px; margin:10px 0 6px; overflow:hidden; }.refund-bar-track > span { display:block; height:100%; border-radius:inherit; background:#eab389; }.refund-row small { color:#a8aebe; font-size:10px; }.advice-mark { display:flex; gap:5px; align-items:center; padding:4px 7px; border-radius:6px; background:#f4f1fd; color:#8e7bcf; font-size:10px; white-space:nowrap; }.advice-list { display:grid; gap:13px; }.advice-item { border:1px solid #eeedf7; border-left:3px solid #a193e5; border-radius:8px; padding:13px 15px; background:#fdfcfe; }.advice-item.refund-advice { border-left-color:#e2ad82; background:#fffdfb; }.advice-labels { display:flex; gap:8px; align-items:center; }.advice-labels span { color:#8b79bd; background:#f1eefb; padding:2px 6px; font-size:9px; border-radius:4px; }.refund-advice .advice-labels span { color:#b38969; background:#faf0e6; }.advice-labels small { color:#aaa9b8; font-size:9px; }.advice-item h4 { font-size:12px; margin:9px 0 7px; line-height:1.6; font-weight:600; }.advice-evidence { color:#8992a6; font-size:10px; line-height:1.8; margin:0; }.advice-item ul { margin:8px 0; padding-left:15px; color:#6e7b94; font-size:11px; line-height:1.9; }.advice-measure { color:#a3a9b8; font-size:9px; line-height:1.7; margin:8px 0 0; }.advice-note { font-size:10px; color:#a6aebe; line-height:1.8; margin:15px 0 0; }.category-table-panel { margin-top:20px; }.sales-table-scroll { overflow-x:auto; }.sales-table-scroll table { width:100%; border-collapse:collapse; white-space:nowrap; font-size:11px; }.sales-table-scroll th { font-weight:500; color:#9ca5b7; background:#fafbfe; padding:12px; text-align:right; }.sales-table-scroll td { color:#65728a; padding:15px 12px; border-bottom:1px solid #f1f3f8; text-align:right; }.sales-table-scroll th:first-child,.sales-table-scroll td:first-child { text-align:left; }.sales-table-scroll .refund-amount { color:#ba947c; }.sales-notes { font-size:10px; color:#9ba4b6; margin:20px 0 0; line-height:1.9; }.sales-notes summary { cursor:pointer; }.sales-notes ul { padding-left:18px; }.sales-downloads { display:flex; gap:18px; align-items:center; flex-wrap:wrap; margin-top:15px; font-size:10px; color:#a8b0be; }.sales-downloads a,.sales-downloads button { color:#8b80b6; text-decoration:none; }.sales-downloads button { border:0; padding:0; background:transparent; cursor:pointer; margin-left:auto; font-size:10px; }.panel-empty { color:#a2abbb; font-size:12px; line-height:1.9; padding:28px 5px; }.sales-empty { min-height:390px; background:#fff; border:1px dashed #dcd9ef; border-radius:15px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:14px; padding:25px; text-align:center; }.sales-empty-icon { display:grid; place-items:center; background:#f2effc; color:#9688d9; border-radius:17px; width:68px; height:68px; }.sales-empty h3 { font-size:19px; margin:0; }.sales-empty p { font-size:12px; line-height:1.9; max-width:360px; color:#929caf; margin:0; }.sales-empty small { color:#a6adba; font-size:10px; }.sales-spinner { width:25px; height:25px; border:3px solid #e7e2fa; border-top-color:#7463e8; border-radius:50%; animation:spin .8s linear infinite; }.sales-error { display:flex; justify-content:space-between; gap:12px; padding:12px; background:#fff0ed; color:#c07e6d; font-size:12px; border-radius:9px; margin-bottom:15px; }.sales-error button { border:0; color:inherit; background:transparent; cursor:pointer; }
